            return ToolResult("(empty file)", False)
        if start > total:
            return ToolResult("Error: start_line %d is past the end of the file (%d lines)" % (start, total), True)
        if end < start:
            return ToolResult("Error: end_line %d is before start_line %d" % (end, start), True)
